<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Configuration Monitor</title>
    <style>
        :root { --ink:#17221f; --muted:#65736e; --paper:#f5f3ed; --card:#fffdf8; --accent:#e56b48; --line:#dfe3dc; --good:#287d5a; }
        * { box-sizing:border-box; } body { margin:0; color:var(--ink); background:radial-gradient(circle at 85% 0%, #dbe8d7 0, transparent 35%),var(--paper); font:15px/1.5 Georgia, serif; }
        .shell { max-width:1200px; margin:auto; padding:42px 24px 70px; } header { display:flex; justify-content:space-between; align-items:end; gap:20px; margin-bottom:36px; }
        h1,h2 { margin:0; font-weight:500; letter-spacing:.01em; } h1 { font-size:clamp(2rem,5vw,4rem); line-height:1; } h2 { font-size:1.35rem; }
        .eyebrow { color:var(--accent); font:700 11px/1.2 Arial,sans-serif; letter-spacing:.15em; text-transform:uppercase; margin-bottom:12px; } .subtle { color:var(--muted); }
        .button { border:1px solid var(--ink); background:var(--ink); color:white; padding:9px 14px; border-radius:4px; cursor:pointer; font:600 12px Arial,sans-serif; } .button.light { background:transparent; color:var(--ink); }
        .metrics { display:grid; grid-template-columns:repeat(4,1fr); gap:12px; margin-bottom:34px; } .metric,.panel { background:var(--card); border:1px solid var(--line); border-radius:6px; }
        .metric { padding:20px; } .metric strong { display:block; font-size:2rem; font-weight:500; } .metric span { color:var(--muted); font:11px Arial,sans-serif; text-transform:uppercase; letter-spacing:.1em; }
        .panel { padding:22px; margin-top:16px; } table { width:100%; border-collapse:collapse; font-family:Arial,sans-serif; font-size:13px; } th { text-align:left; color:var(--muted); font-size:10px; letter-spacing:.1em; text-transform:uppercase; } th,td { padding:13px 8px; border-bottom:1px solid var(--line); vertical-align:top; } .status { color:var(--good); font-weight:700; } .status.failed { color:#b33e32; } .status.pending { color:#a06b19; }
        .change { margin:5px 0; } .old { color:#a24439; } .new { color:var(--good); } code { background:#eef0ea; padding:2px 4px; border-radius:3px; font-size:12px; } form.inline { display:inline; }
        @media(max-width:760px) { header { display:block; } header .button { margin-top:18px; } .metrics { grid-template-columns:repeat(2,1fr); } .panel { overflow:auto; } table { min-width:650px; } }
    </style>
</head>
<body>
<main class="shell">
    <header><div><div class="eyebrow">Operations</div><h1>Configuration<br>monitoring.</h1><p class="subtle">A live audit trail for the files your team depends on.</p></div><button class="button" onclick="addFile()">+ Add file</button></header>
    <section class="metrics"><div class="metric"><strong>{{ $files->count() }}</strong><span>Monitored files</span></div><div class="metric"><strong>{{ $metrics['changes'] }}</strong><span>Changes detected</span></div><div class="metric"><strong>{{ $metrics['sent'] }}</strong><span>Notifications sent</span></div><div class="metric"><strong>{{ $metrics['failed'] }}</strong><span>Failed notifications</span></div></section>
    <section class="panel"><h2>Monitored files</h2><table><thead><tr><th>File</th><th>Type</th><th>Status</th><th>Last modified</th><th>Hash</th><th></th></tr></thead><tbody>@forelse($files as $file)<tr><td><code>{{ $file->path }}</code></td><td>{{ strtoupper($file->file_type) }}</td><td class="status">{{ $file->is_active ? 'Active' : 'Stopped' }}</td><td>{{ $file->last_modified_at?->diffForHumans() ?? 'Waiting for snapshot' }}</td><td><code>{{ $file->last_hash ? substr($file->last_hash, 0, 12).'...' : '—' }}</code></td><td><form class="inline" method="post" action="/api/watch/{{ urlencode($file->path) }}"><input type="hidden" name="_method" value="DELETE"><button class="button light" type="submit">Stop</button></form></td></tr>@empty<tr><td colspan="6" class="subtle">No files are being monitored yet.</td></tr>@endforelse</tbody></table></section>
    <section class="panel"><h2>Recent events</h2><table><thead><tr><th>Event</th><th>File</th><th>Type</th><th>Status</th><th>Detected</th><th>Changes</th><th>Actions</th></tr></thead><tbody>@forelse($events as $event)<tr><td><code>#{{ $event->id }}</code></td><td>{{ basename($event->monitoredFile?->path ?? $event->payload['file'] ?? 'unknown') }}</td><td>{{ $event->event_type }}</td><td class="status {{ $event->status }}">{{ $event->status }}</td><td>{{ $event->detected_at?->diffForHumans() }}</td><td>@foreach(($event->payload['changes']['updated'] ?? []) as $key => $change)<div class="change"><code>{{ $key }}</code>: <span class="old">{{ json_encode($change['old']) }}</span> → <span class="new">{{ json_encode($change['new']) }}</span></div>@endforeach @foreach(($event->payload['changes']['type_changes'] ?? []) as $key => $change)<div class="change"><code>{{ $key }}</code>: <span class="old">{{ $change['oldType'] }}</span> → <span class="new">{{ $change['newType'] }}</span></div>@endforeach @foreach(($event->payload['changes']['added'] ?? []) as $key => $value)<div class="change"><code>{{ $key }}</code>: <span class="new">added {{ json_encode($value) }}</span></div>@endforeach @foreach(($event->payload['changes']['removed'] ?? []) as $key => $value)<div class="change"><code>{{ $key }}</code>: <span class="old">removed {{ json_encode($value) }}</span></div>@endforeach</td><td><form class="inline" method="post" action="/api/events/{{ $event->id }}/retry"><button class="button light" type="submit">Retry</button></form></td></tr>@empty<tr><td colspan="7" class="subtle">No configuration changes yet.</td></tr>@endforelse</tbody></table></section>
</main>
<script>async function addFile(){const path=prompt('Path inside WATCH_ROOT:','{{ config('monitoring.root') }}/.env');if(!path)return;const response=await fetch('/api/watch',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({path})});if(!response.ok)alert((await response.json()).message||'Unable to add file');else location.reload();}</script>
</body></html>